html:
{%- import "altor_project/templates/print/altor_print.html" as ap with context -%}
{%- set c = altor_company(doc.company, doc) -%}
{{ ap.styles(c) }}
{%- set by_boq = False -%}
{#- shared body for "Quotation" (item wise) and "Quotation Altor" (BOQ work package wise); set by_boq before including -#}
{%- set p = altor_party(doc) -%}
<div class="ap letter">
{{ ap.header(c, "QUOTATION", "عرض سعر", [
    ["Quotation No.", doc.name],
    ["Date", ap.date(doc.transaction_date)],
    ["Valid Till", ap.date(doc.valid_till)],
    ["Revision", doc.amended_from and ("Rev. of " ~ doc.amended_from)]
]) }}
{{ ap.two_boxes(ap.party_box("To", p), ap.info_box("Project", [
    ["Project", doc.get("custom_project")],
    ["Location", doc.get("custom_location")],
    ["LPO Ref.", doc.get("lpo_ref") and (doc.lpo_ref ~ (" dated " ~ ap.date(doc.lpo_date) if doc.get("lpo_date") else ""))],
    ["BOQ Ref.", doc.get("custom_bill_of_quantity")],
    ["Sales Person", doc.get("sales_person")]
])) }}
<div class="subject">Subject: {{ doc.get("custom_subject") or doc.get("custom_scope_of_work") or doc.get("custom_project") or ("Quotation for " ~ (doc.get("items")[0].item_name if doc.get("items") else "the subjected works")) }}</div>
<p>Dear Sir / Madam,</p>
<p>Thank you for your enquiry. We are pleased to submit our most competitive offer for the subjected works as detailed below.</p>

<table class="items">
  <thead><tr><th style="width:6%">#</th><th>Description of Work <span class="ar">وصف العمل</span></th><th class="right" style="width:24%">Amount ({{ doc.currency }}) <span class="ar">المبلغ</span></th></tr></thead>
  <tbody>
  {%- set groups = altor_boq(doc) if by_boq else [] -%}
  {%- if groups %}
    {%- for g in groups %}
    <tr><td>{{ loop.index }}</td><td><div class="item-name">{{ g.title }}</div>
      {%- set lines = [] -%}{%- for it in g["items"] %}{% for l in it.lines %}{% set _ = lines.append(l) %}{% endfor %}{% endfor -%}
      {%- if lines %}<ul>{% for l in lines %}<li>{{ l }}</li>{% endfor %}</ul>{% endif %}</td>
      <td class="right">{{ ap.amt(g.total) }}</td></tr>
    {%- endfor %}
  {%- else %}
    {%- for item in doc.get("items") %}
    <tr><td>{{ loop.index }}</td><td><div class="item-name">{{ item.item_name }}</div>
      {%- if item.description and item.description | striptags | trim != item.item_name %}{{ ap.bullets(item.description) }}{% endif %}
      {%- if item.qty != 1 %}<div class="muted">{{ ap.num(item.qty) }} {{ item.uom }} &times; {{ ap.amt(item.rate) }}</div>{% endif %}</td>
      <td class="right">{{ ap.amt(item.amount) }}</td></tr>
    {%- endfor %}
  {%- endif %}
  </tbody>
</table>
{{ ap.totals(doc) }}

{%- if doc.get("custom_quotation_content") %}<div class="sec">{{ doc.custom_quotation_content }}</div>{% endif %}
{{ ap.section("Payment Terms", ap.payment_terms(doc)) }}
{{ ap.section("Terms & Conditions", doc.get("terms")) }}
{%- set days = altor_validity_days(doc) %}
{%- if days %}<p class="muted" style="margin-top:8px">This offer is valid for {{ days }} days from the date of quotation.</p>{% endif %}
<p style="margin-top:12px">We trust our offer meets your requirements and look forward to receiving your valued order.</p>
<p>Yours faithfully,</p>
{{ ap.signatures(c, ["For " ~ c.name, "Accepted by Client"]) }}
{{ ap.footer(c) }}
</div>
